/// Reuse one admitted authoring operation, including the original hold/deadline.
/// Fresh source budgets are configuration, never serialized authority.
pub(crate) struct GuideGenerationContext<'a> {
    pub(crate) application: &'a ApplicationServices,
    pub(crate) pool: &'a DbPool,
    pub(crate) budget: TeletextDesignDocumentBudget,
    pub(crate) encoding: TeletextChannelDocumentEncodingPolicy,
    pub(crate) limits: TeletextGuideSourceCheckLimits,
    pub(crate) deadline: Instant,
    pub(crate) hold: TeletextWorkHold,
}

/// Native source/role proof plus its original conservative monotonic expiry.
/// The monotonic deadline is neither persisted nor included in artifact framing.
#[derive(Debug)]
pub(crate) struct GuideOutputQualification {
    pub(crate) qualification: TeletextGuideGenerationQualification,
    pub(crate) limits: TeletextGuideSourceCheckLimits,
    pub(crate) deadline: Instant,
}

impl GuideOutputQualification {
    fn new(
        qualification: TeletextGuideGenerationQualification,
        limits: TeletextGuideSourceCheckLimits,
    ) -> Result<Self, NativeTeletextGenerationError> {
        let monotonic = Instant::now();
        let wall = Utc::now();
        qualification
            .validate_current(wall)
            .map_err(|_| NativeTeletextGenerationError::GuideFreshnessRequired)?;
        let deadline = qualification
            .valid_until
            .signed_duration_since(wall)
            .to_std()
            .ok()
            .and_then(|remaining| monotonic.checked_add(remaining))
            .unwrap_or(monotonic);
        Ok(Self {
            qualification,
            limits,
            deadline,
        })
    }
}

fn check_deadline(deadline: Instant) -> Result<(), NativeTeletextGenerationError> {
    if Instant::now() >= deadline {
        Err(NativeTeletextDesignError::TimedOut.into())
    } else {
        Ok(())
    }
}

pub(super) async fn capture(
    operation: &GuideGenerationContext<'_>,
    source: &TeletextGuideSourceFence,
) -> Result<CapturedTeletextGuide, NativeTeletextGenerationError> {
    check_deadline(operation.deadline)?;
    let limits = operation.limits;
    let mut budget = GuideReadBudget::new_with_expansion(
        GuideReadLimits {
            max_records: limits.max_records,
            max_source_bytes: limits.max_source_bytes,
        },
        GuideExpansionLimits {
            max_nodes: limits.max_model_nodes,
            max_bytes: limits.max_model_bytes,
        },
    );
    let captured = capture_source_bound_teletext_guide_with_hold(
        operation.pool,
        &source.channel_ids,
        source.captured_at,
        &mut budget,
        operation.deadline,
        GuideSnapshotDigestLimits {
            max_fields: limits.max_digest_fields,
            max_bytes: limits.max_digest_bytes,
        },
        operation.hold.clone(),
    )
    .await
    .map_err(|error| capture_error(&error))?;
    if captured.guide_source() != Some(source) {
        return Err(NativeTeletextGenerationError::GuideFreshnessRequired);
    }
    Ok(captured)
}

fn capture_error(
    error: &super::teletext_guide::TeletextGuideCaptureError,
) -> NativeTeletextGenerationError {
    match error {
        super::teletext_guide::TeletextGuideCaptureError::TimedOut => {
            NativeTeletextDesignError::TimedOut.into()
        }
        super::teletext_guide::TeletextGuideCaptureError::Worker => {
            NativeTeletextGenerationError::WorkerFailed
        }
        _ => NativeTeletextGenerationError::GuideFreshnessRequired,
    }
}

pub(super) fn qualify(
    captured: &CapturedTeletextGuide,
    source: &TeletextGuideSourceFence,
    inputs: Option<&TeletextSavedGuideInputs>,
    scope_expiry: Option<chrono::DateTime<Utc>>,
    deadline: Instant,
) -> Result<TeletextGuideGenerationQualification, NativeTeletextGenerationError> {
    check_deadline(deadline)?;
    let inputs = inputs
        .filter(|inputs| inputs.has_guide_channels())
        .ok_or(NativeTeletextGenerationError::GuideFreshnessRequired)?;
    let mut present = false;
    for (contract, schema) in [
        (TeletextPageContract::V1, 1),
        (TeletextPageContract::V2, 2),
        (TeletextPageContract::V3, 3),
    ] {
        if let Some(bytes) = inputs.request(contract) {
            let saved = TeletextPagesRequest::from_json_for_schema(bytes, schema)
                .map_err(|_| NativeTeletextGenerationError::GuideFreshnessRequired)?;
            let expected_bytes = captured
                .request_bytes(&saved.generation, schema)
                .map_err(|error| capture_error(&error))?;
            let expected = TeletextPagesRequest::from_json_for_schema(&expected_bytes, schema)
                .map_err(|_| NativeTeletextGenerationError::GuideFreshnessRequired)?;
            // Wire validation alone cannot prove Current/Next/Continuing roles.
            // This comparison also covers every original programme/segment fact.
            if saved != expected {
                return Err(NativeTeletextGenerationError::GuideFreshnessRequired);
            }
            present = true;
        }
        check_deadline(deadline)?;
    }
    if !present {
        return Err(NativeTeletextGenerationError::GuideFreshnessRequired);
    }
    let mut qualification = source
        .qualify_current(
            captured
                .snapshot()
                .channels()
                .iter()
                .flat_map(ersatzrs_infra::xmltv::CapturedGuideChannel::occurrences),
            Utc::now(),
        )
        .map_err(|_| NativeTeletextGenerationError::GuideFreshnessRequired)?;
    if let Some(expiry) = scope_expiry {
        qualification.valid_until = qualification.valid_until.min(expiry);
    }
    qualification
        .validate_current(Utc::now())
        .map_err(|_| NativeTeletextGenerationError::GuideFreshnessRequired)?;
    check_deadline(deadline)?;
    Ok(qualification)
}

pub(super) fn fingerprint(
    service: &EncodedTeletextAuthoredService,
    qualification: &TeletextGuideGenerationQualification,
    version: u16,
    deadline: Instant,
) -> Result<String, NativeTeletextGenerationError> {
    check_deadline(deadline)?;
    let service_digest = artifact_digest_for_version(
        service,
        TELETEXT_LIFECYCLE_GENERATION_ARTIFACT_VERSION,
        deadline,
    )?;
    let mut hash = Sha256::new();
    hash.update(b"ErsatzRS.Teletext.GuideCompiledService");
    hash.update(version.to_be_bytes());
    hash.update(service_digest.as_bytes());
    let source = &qualification.source;
    hash.update(source.version.to_be_bytes());
    hash.update(source.context_digest_version.to_be_bytes());
    hash.update(source.context_digest);
    hash.update(
        u64::try_from(source.channel_ids.len())
            .map_err(|_| NativeTeletextGenerationError::ArtifactMismatch)?
            .to_be_bytes(),
    );
    for id in &source.channel_ids {
        hash.update(id.to_be_bytes());
    }
    for instant in [
        source.captured_at,
        source.start,
        source.finish,
        qualification.valid_until,
    ] {
        hash.update(instant.timestamp().to_be_bytes());
        hash.update(instant.timestamp_subsec_nanos().to_be_bytes());
    }
    for text in [&source.locale, &source.timezone] {
        hash.update(
            u64::try_from(text.len())
                .map_err(|_| NativeTeletextGenerationError::ArtifactMismatch)?
                .to_be_bytes(),
        );
        hash.update(text.as_bytes());
    }
    let mut result = String::with_capacity(64);
    for byte in hash.finalize() {
        let _ = write!(result, "{byte:02x}");
    }
    check_deadline(deadline)?;
    Ok(result)
}
